function inputField(f){let [name,label,type='text',val='',opts=[]]=f;let v=val??'';if(type==='select')return`<div class="field"><label for="fld_${name}">${esc(label)}</label><select name="${name}" id="fld_${name}">${opts.map(o=>`<option value="${esc(typeof o==='string'?o:o[0])}" ${v===(typeof o==='string'?o:o[0])?'selected':''}>${esc(typeof o==='string'?o:o[1])}</option>`).join('')}</select></div>`;if(type==='textarea')return`<div class="field wide"><label for="fld_${name}">${esc(label)}</label><textarea name="${name}" id="fld_${name}" rows="3">${esc(v)}</textarea></div>`;return`<div class="field"><label for="fld_${name}">${esc(label)}</label><input name="${name}" id="fld_${name}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(v)}" ${name==='date'?'required':''}/></div>`}
function modal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalLayer').hidden=false;document.body.style.overflow='hidden'}
function closeModal(){$('#modalLayer').hidden=true;document.body.style.overflow=''}
function formModal(kind,title,fields,description=''){modal(title,`<form id="entryForm" data-kind="${kind}">${description?`<p class="small muted">${description}</p>`:''}<div class="form-grid">${fields.map(inputField).join('')}</div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Cancel</button><button class="btn btn-primary" type="submit">Save entry ✓</button></div></form>`)}
function showEntry(kind){let date=['date','Date','date',selectedDate],notes=['notes','Notes','textarea'];if(kind==='food'){let opts=state.foodLibrary.map(x=>x.food).sort();formModal('food','Log a meal',[date,['meal','Meal','select','Breakfast',['Breakfast','Lunch','Dinner','Snack','Pre-workout','Post-workout']],['food','Food / packaged item','select',opts[0],opts.map(x=>[x,x])],['servings','Number of listed servings','number',1],notes],'Choose a food and multiply by its reference serving size (for example 1.5 × 40 g oats = 60 g oats). You can add new foods to the library.');let sel=$('#fld_food');if(sel&&state.foodLibrary.find(x=>x.food==='Mess breakfast eggs (3)'))sel.value='Mess breakfast eggs (3)';}
 else if(kind==='workout'){formModal(kind,'Log a strength exercise',[date,['day','Workout name','select',weekday(selectedDate),['Lower A','Upper A','Recovery','Lower B','Upper B','Other']],['exercise','Exercise','text','Leg press'],['sets','Sets','number',3],['reps','Reps per set','number',10],['weight_kg','Weight / resistance (kg)','number',0],['rpe','Effort RPE (1–10)','number',7],['duration_min','Duration (minutes)','number',45],notes])}
 else if(kind==='football')formModal(kind,'Log a football session',[date,['duration_min','Duration (min)','number',60],['rpe','Difficulty 1–10','number',7],['distance_km','Distance km (optional)','number',''],['skill','Goals / skills / match notes','text',''],notes]);
 else if(kind==='habits'){let existing=state.dailyHabits.find(x=>x.date===selectedDate)||{};formModal(kind,'Daily recovery & habits',[date,['sleep_h','Sleep hours','number',existing.sleep_h||8],['water_l','Drinking water (L)','number',existing.water_l||3],['steps','Daily steps','number',existing.steps||''],['energy','Energy (1–5)','number',existing.energy||3],['stress','Stress (1–5)','number',existing.stress||3],['soreness','Soreness (1–5)','number',existing.soreness||2],['skin_care','Skin-care completed','select',existing.skin_care||'No',['No','Yes']],['hair_care','Hair care completed','select',existing.hair_care||'No',['No','Yes']],['fruit_servings','Fruit servings','number',existing.fruit_servings||0],['veg_servings','Vegetable servings','number',existing.veg_servings||0],notes]);}
 else if(kind==='measurement'){let latest=state.measurements[0]||{};formModal(kind,'Body measurement check-in',[date,['weight_kg','Weight (kg)','number',latest.weight_kg||75],['body_fat_pct','Body-fat estimate %','number',latest.body_fat_pct||25],['waist_cm','Waist (cm)','number',''],['chest_cm','Chest (cm)','number',''],['arm_cm','Arm/biceps (cm)','number',''],['shoulder_cm','Shoulders (cm)','number',''],['hip_cm','Hip (cm)','number',''],['thigh_cm','Thigh (cm)','number',''],notes],'Use the same measuring method and time of day. Body-fat values are estimates.');}
 else if(kind==='purchase'){formModal(kind,'Record an actual grocery purchase',[date,['store','Purchased from','select','Zepto',['Zepto','Blinkit','Mess','Other']],['item','Product / item','text','Soy chunks'],['qty','Quantity / packs','number',1],['unit','Unit','text','pack'],['unit_price','Price per pack (₹)','number',50],['category','Spending category','select','Protein',['Protein','Mess protein','Dairy','Pantry','Produce','Supplement','Healthy fats','Other']],notes]);}
 else if(kind==='customFood'){formModal(kind,'Add custom food to nutrition library',[['food','Food name','text',''],['portion','Serving size','number',100],['unit','Serving unit','text','g'],['calories','Calories per serving','number',0],['protein','Protein g per serving','number',0],['carbs','Carbs g per serving','number',0],['fat','Fat g per serving','number',0],['fibre','Fibre g per serving','number',0],['calcium','Calcium mg per serving','number',0],['iron','Iron mg per serving','number',0],['vitamin_c','Vitamin C mg per serving','number',0],['omega3','ALA omega-3 g per serving','number',0],['cost','Cost ₹ per serving','number',0],notes],'Use values from a trusted nutrition label or weighed ingredient.');}
 else if(kind==='supplement'){formModal(kind,'Supplement / medication tracking',[date,['item','Supplement name','text','Creatine monohydrate'],['amount','Amount','number',3],['unit','Unit','text','g'],['notes','Label, tolerance, medical advice','textarea','']]);}
 else if(kind==='micros'){formModal(kind,'Manual micronutrient log',[date,['b12','Vitamin B12 mcg','number',0],['vitamin_d','Vitamin D mcg','number',0],['magnesium','Magnesium mg','number',0],['zinc','Zinc mg','number',0],['iodized_salt','Iodized salt?','select','Yes',['Yes','No']],notes],'Only enter credible label- or database-based values; avoid guessing.');}
 else if(kind==='review'){formModal(kind,'Weekly review',[['date','Week starting Monday','date',startWeek(selectedDate)],['average_weight','Average weight kg','number',75],['average_protein','Average protein g','number',0],['gym_visits','Gym visits','number',0],['football_sessions','Football sessions','number',0],['spending','Spending ₹','number',0],notes]);}
}
function saveEntry(e){e.preventDefault();let f=e.target,kind=f.dataset.kind,values=Object.fromEntries(new FormData(f));let numeric={food:['servings'],workout:['sets','reps','weight_kg','rpe','duration_min'],football:['duration_min','rpe','distance_km'],habits:['sleep_h','water_l','steps','energy','stress','soreness','fruit_servings','veg_servings'],measurement:['weight_kg','body_fat_pct','waist_cm','chest_cm','arm_cm','shoulder_cm','hip_cm','thigh_cm'],purchase:['qty','unit_price'],customFood:['portion','calories','protein','carbs','fat','fibre','calcium','iron','vitamin_c','omega3','cost'],supplement:['amount'],micros:['b12','vitamin_d','magnesium','zinc'],review:['average_weight','average_protein','gym_visits','football_sessions','spending']}[kind]||[];for(let k of numeric)values[k]=values[k]===''?null:Number(values[k]);if(kind==='food'){let x=foodMacros(values.food,values.servings);if(!Object.keys(x).length){toast('Select a food from the library');return}state.foodLogs.push({...values,...x});}
 else if(kind==='habits'){state.dailyHabits=state.dailyHabits.filter(x=>x.date!==values.date);state.dailyHabits.push(values)}
 else if(kind==='measurement'){state.measurements=state.measurements.filter(x=>x.date!==values.date);state.measurements.push(values)}
 else if(kind==='workout')state.workouts.push(values);
 else if(kind==='football')state.football.push(values);
 else if(kind==='purchase')state.purchases.push({...values,total:(values.qty||0)*(values.unit_price||0)});
 else if(kind==='customFood'){if(!values.food?.trim()){toast('Food name is required');return}state.foodLibrary=state.foodLibrary.filter(x=>x.food!==values.food);state.foodLibrary.push(values)}
 else if(kind==='supplement'){state.supplements.push(values)}
 else if(kind==='micros'){state.microsDaily=state.microsDaily||[];state.microsDaily=state.microsDaily.filter(x=>x.date!==values.date);state.microsDaily.push(values)}
 else if(kind==='review'){state.weeklyReviews=state.weeklyReviews.filter(x=>x.date!==values.date);state.weeklyReviews.push(values)}
 save();closeModal();render();toast('Saved successfully ✓')}
function showRecipe(id){let r=state.recipes.find(x=>x.id===id);if(!r)return;modal(r.name,`<div class="recipe-detail"><img src="${imageFor(r)}" alt="Illustrated ${esc(r.name)}"/><div class="filters" style="margin:14px 0">${tag(r.category)}${tag(r.minutes+' min','blue-tag')}${tag(r.protein+'g protein','orange-tag')}</div><div class="three-cols"><div class="info-block"><strong>${r.calories}</strong><small>Approx. kcal</small></div><div class="info-block"><strong>${r.carbs} g</strong><small>Carbs</small></div><div class="info-block"><strong>${r.fat} g</strong><small>Fat</small></div></div><h3>Ingredients (one serving)</h3><p class="small muted">${esc(r.ingredients)}</p><h3>Preparation</h3><ol>${r.steps.split('|').map(x=>`<li>${esc(x.replace(/^\s*\d+\.\s*/,''))}</li>`).join('')}</ol><div class="safety"><b>Food-safety note:</b> ${esc(r.safety)}</div><p class="small muted">Equipment: ${esc(r.equipment)} · Values approximate; mess portions and oil amounts vary.</p><button class="btn btn-primary" data-add-recipe="${r.id}">＋ Add this recipe to diary</button></div>`)}
function addRecipe(id){let r=state.recipes.find(x=>x.id===id);if(!r)return;let name='Recipe: '+r.name;if(!state.foodLibrary.find(x=>x.food===name))state.foodLibrary.push({food:name,portion:1,unit:'recipe',calories:r.calories,protein:r.protein,carbs:r.carbs,fat:r.fat,fibre:r.fibre,calcium:0,iron:0,vitamin_c:0,omega3:0,cost:0,notes:'Recipe estimate; micronutrients and cost not calculated'});state.foodLogs.push({date:selectedDate,meal:'Dinner',food:name,servings:1,...foodMacros(name,1),notes:'Recipe log. Adjust if you changed ingredients.'});save();closeModal();render();toast('Recipe added to your food diary ✓')}
function editGrocery(index){let g=state.groceries[index];if(!g)return;let fields=[['first_order_packs','Packs in first order','number',g.first_order_packs],['weekly_use','Actual quantity used per week ('+g.pack_unit+')','number',g.weekly_use],['zepto_price','Zepto price ₹','number',g.zepto_price??''],['blinkit_price','Blinkit price ₹','number',g.blinkit_price??''],['pack_size','Pack size ('+g.pack_unit+')','number',g.pack_size],['priority','Priority','select',g.priority,['Essential','Optional','As needed']]];modal('Edit '+g.item,`<form id="groceryEditForm" data-index="${index}"><div class="form-grid">${fields.map(inputField).join('')}</div><p class="small muted">For products with no refrigeration, don't plan bulk meat/dairy storage. A 1 kg oats pack can last for several weeks.</p><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close-modal>Cancel</button><button class="btn btn-primary" type="submit">Update budget</button></div></form>`)}
function saveGrocery(e){e.preventDefault();let f=e.target,g=state.groceries[Number(f.dataset.index)];if(!g)return;let vals=Object.fromEntries(new FormData(f));for(let [k,v] of Object.entries(vals)){if(['priority'].includes(k))g[k]=v;else g[k]=v===''?null:Number(v)}save();closeModal();render();toast('Price model updated ✓')}
function download(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function exportCSV(){let headers=['Date','Meal','Food','Servings','Calories','Protein g','Carbs g','Fat g','Fibre g','Cost INR','Notes'];let csv=[headers,...state.foodLogs.map(x=>[x.date,x.meal,x.food,x.servings,x.calories,x.protein,x.carbs,x.fat,x.fibre,x.cost,x.notes])].map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'Fit_OS_Food_Log.csv')}
function exportJSON(){download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'Fit_OS_Full_Backup_'+localDate(new Date())+'.json')}
