 fs['START HERE']=[['SECTION','INSTRUCTIONS'],['Fit OS','Upload this .xlsx on Fit OS website to update its charts, budgets and logs immediately on this device.'],['How to edit','Put records on row 2 onward under existing column headers; keep Date as YYYY-MM-DD.'],['Data safety','The website saves locally in your browser. Export often. Do not publish personal log files to a public GitHub repository.'],['Refrigeration','No fridge: same-day chilled dairy, and no unattended meat / cooked-rice storage.']];
 fs['Dashboard']=[['Indicator','Value'],['First order without whey',firstCost(false)],['First order with optional 1kg whey',firstCost(true)],['Estimated weekly usage',weeklyCost()],['Weekly budget target',P.weekly_budget_inr],['Protein target g',P.protein_goal_g],['Food diary entries',state.foodLogs.length],['Workout entries',state.workouts.length],['Football sessions',state.football.length],['Measurements',state.measurements.length],['Last export',new Date().toISOString()]];
 const props=[['Name',P.name],['Campus',P.institution],['Height cm',P.height_cm],['Starting weight kg',P.start_weight_kg],['Body fat estimate %',P.body_fat_pct],['Protein goal g',P.protein_goal_g],['Protein minimum g',P.protein_min_g],['Calories target kcal',P.calorie_goal_kcal],['Carbs goal g',P.carb_goal_g],['Fat goal g',P.fat_goal_g],['Fibre goal g',P.fibre_goal_g],['Water goal L',P.water_goal_l],['Sleep goal h',P.sleep_goal_h],['Gym visits weekly',P.weekly_gym_goal],['Football sessions weekly',P.weekly_football_goal],['Weekly grocery budget INR',P.weekly_budget_inr],['Main start date',P.start_date],['Refrigerator access',P.storage],['Included mess eggs daily',P.mess_eggs_daily]];
