 add('Food Library',['Food','Serving Size','Unit','Calories','Protein g','Carbs g','Fat g','Fibre g','Calcium mg','Iron mg','Vitamin C mg','Omega-3 ALA g','Cost INR','Notes'],state.foodLibrary,['food','portion','unit','calories','protein','carbs','fat','fibre','calcium','iron','vitamin_c','omega3','cost','notes']);
 add('Food Log',['Date','Meal','Food','Servings','Calories','Protein g','Carbs g','Fat g','Fibre g','Calcium mg','Iron mg','Vitamin C mg','Omega-3 ALA g','Cost INR','Notes'],state.foodLogs,['date','meal','food','servings','calories','protein','carbs','fat','fibre','calcium','iron','vitamin_c','omega3','cost','notes']);
 add('Daily Habits',['Date','Sleep h','Water L','Steps','Energy 1-5','Stress 1-5','Soreness 1-5','Skin care Y/N','Hair care Y/N','Fruit servings','Veg servings','Notes'],state.dailyHabits,['date','sleep_h','water_l','steps','energy','stress','soreness','skin_care','hair_care','fruit_servings','veg_servings','notes']);
