 add('Measurements',['Date','Weight kg','Body Fat %','Waist cm','Chest cm','Arm cm','Shoulder cm','Hip cm','Thigh cm','Notes'],state.measurements,['date','weight_kg','body_fat_pct','waist_cm','chest_cm','arm_cm','shoulder_cm','hip_cm','thigh_cm','notes']);
