 fs['Groceries']=[['Item','Category','Pack Size','Pack Unit','Zepto Price INR','Blinkit Price INR','First Order Packs','Weekly Use','Weekly Unit','Storage','Priority','Notes','Best Price INR','First Order INR','Weekly Usage INR'],...state.groceries.map(x=>[x.item,x.category,x.pack_size,x.pack_unit,x.zepto_price??'',x.blinkit_price??'',x.first_order_packs,x.weekly_use,x.weekly_unit,x.storage,x.priority,x.notes,gb(x)??'',gb(x)===null?'':gb(x)*x.first_order_packs,gb(x)===null?'':gb(x)*x.weekly_use/x.pack_size])];
