 add('Weekly Review',['Week Start','Avg Weight kg','Avg Protein g','Gym Visits','Football Sessions','Spending INR','Notes'],state.weeklyReviews,['date','average_weight','average_protein','gym_visits','football_sessions','spending','notes']);
