 let purch=get('Purchases','Purchase Log');if(purch){let items=sheetRecords(purch,['Date','Product'])||sheetRecords(purch,['Date','Item'])||[];state.purchases=items.map(x=>{let qty=nval(value(x,'Quantity / Packs','Quantity / packs'),1),unit_price=nval(value(x,'Unit Price INR','Actual price / pack'),0);return{date:parseDay(value(x,'Date')),store:String(value(x,'Store','Store/channel')||'Other'),item:String(value(x,'Item','Product')||''),qty,unit:String(value(x,'Unit')||'pack'),unit_price,total:nval(value(x,'Total INR','Total'),qty*unit_price),category:String(value(x,'Category')||'Other'),notes:String(value(x,'Notes')||'')}}).filter(x=>validDate(x.date)&&x.item);touched.push('Purchases');mapped+=state.purchases.length}
 let grocery=get('Groceries');if(grocery){let items=sheetRecords(grocery,['Item','Pack Size'])||[];let a=items.map(x=>({item:String(value(x,'Item')||''),category:String(value(x,'Category')||''),pack_size:nval(value(x,'Pack Size'),1),pack_unit:String(value(x,'Pack Unit')||'g'),zepto_price:nval(value(x,'Zepto Price INR')),blinkit_price:nval(value(x,'Blinkit Price INR')),first_order_packs:nval(value(x,'First Order Packs'),0),weekly_use:nval(value(x,'Weekly Use'),0),weekly_unit:String(value(x,'Weekly Unit')||'g'),storage:String(value(x,'Storage')||''),priority:String(value(x,'Priority')||'Optional'),notes:String(value(x,'Notes')||'')})).filter(x=>x.item);if(a.length>=5){state.groceries=a;touched.push('Groceries');mapped+=a.length}}
 let rec=get('Recipes');if(rec){let items=sheetRecords(rec,['ID','Name'])||[];let a=items.map(x=>({id:String(value(x,'ID')||''),name:String(value(x,'Name')||''),category:String(value(x,'Category')||''),minutes:String(value(x,'Time','Minutes')||''),equipment:String(value(x,'Equipment')||''),calories:nval(value(x,'Calories'),0),protein:nval(value(x,'Protein g'),0),carbs:nval(value(x,'Carbs g'),0),fat:nval(value(x,'Fat g'),0),fibre:nval(value(x,'Fibre g'),0),ingredients:String(value(x,'Ingredients')||''),steps:String(value(x,'Steps')||''),safety:String(value(x,'Food Safety')||''),image:String(value(x,'Image')||'salad')})).filter(x=>x.id&&x.name&&x.steps);if(a.length>=5){state.recipes=a;touched.push('Recipes');mapped+=a.length}}
 let menu=get('Mess Menu');if(menu){let items=sheetRecords(menu,['Weekday','Breakfast'])||[];let a=items.map(x=>({day:String(value(x,'Weekday')||''),breakfast:String(value(x,'Breakfast')||''),lunch:String(value(x,'Lunch')||''),snacks:String(value(x,'Snacks')||''),dinner:String(value(x,'Dinner')||''),gym:String(value(x,'Gym')||''),football:String(value(x,'Football')||'No'),strategy:String(value(x,'Nutrition Strategy')||'')})).filter(x=>dayNames.includes(x.day));if(a.length===7){state.menu=a;touched.push('Mess Menu');mapped+=7}}
 let plan=get('Gym Plan');if(plan){let items=sheetRecords(plan,['Day','Exercise'])||[];let a=items.map(x=>({day:String(value(x,'Day')||''),session:String(value(x,'Workout')||''),exercise:String(value(x,'Exercise')||''),sets:nval(value(x,'Sets'),0),reps:String(value(x,'Reps Target')||''),notes:String(value(x,'Notes')||'')})).filter(x=>x.exercise);if(a.length>=5){state.workoutPlan=a;touched.push('Gym Plan');mapped+=a.length}}
 let forecast=get('Forecast');if(forecast){let items=sheetRecords(forecast,['Month','Fat Lost'])||[];let a=items.map(x=>({month:nval(value(x,'Month'),0),fat_lost_kg:nval(value(x,'Fat Lost kg'),0),muscle_gained_kg:nval(value(x,'Muscle Gain kg'),0),weight_kg:nval(value(x,'Projected Weight kg'),0),body_fat_pct:nval(value(x,'Projected Body Fat %'),0),scenario:String(value(x,'Notes')||'Illustrative')})).filter(x=>x.weight_kg>0);if(a.length===13){state.forecast=a;touched.push('Forecast');mapped+=a.length}}
 let micros=get('Micros Daily');if(micros){let items=sheetRecords(micros,['Date','Vitamin B12'])||[];state.microsDaily=items.map(x=>({date:parseDay(value(x,'Date')),b12:nval(value(x,'Vitamin B12 mcg'),0),vitamin_d:nval(value(x,'Vitamin D mcg'),0),magnesium:nval(value(x,'Magnesium mg'),0),zinc:nval(value(x,'Zinc mg'),0),iodized_salt:String(value(x,'Iodized Salt Y/N')||'No'),notes:String(value(x,'Notes')||'')})).filter(x=>validDate(x.date));touched.push('Micros Daily');mapped+=state.microsDaily.length}
 let reviews=get('Weekly Review');if(reviews){let items=sheetRecords(reviews,['Week Start','Avg Weight'])||[];state.weeklyReviews=items.map(x=>({date:parseDay(value(x,'Week Start')),average_weight:nval(value(x,'Avg Weight kg'),0),average_protein:nval(value(x,'Avg Protein g'),0),gym_visits:nval(value(x,'Gym Visits'),0),football_sessions:nval(value(x,'Football Sessions'),0),spending:nval(value(x,'Spending INR'),0),notes:String(value(x,'Notes')||'')})).filter(x=>validDate(x.date));touched.push('Weekly Review');mapped+=state.weeklyReviews.length}
 let supplement=get('Supplement Log');if(supplement){let items=sheetRecords(supplement,['Date','Supplement'])||[];state.supplements=items.map(x=>({date:parseDay(value(x,'Date')),item:String(value(x,'Supplement')||''),amount:nval(value(x,'Amount'),0),unit:String(value(x,'Unit')||'g'),notes:String(value(x,'Notes')||'')})).filter(x=>validDate(x.date)&&x.item);touched.push('Supplement Log');mapped+=state.supplements.length}
 return{touched,mapped}
