async function importFile(file){if(!file)return;try{
 let data=file.name.toLowerCase().endsWith('.json')?JSON.parse(await file.text()):null;
 if(data){if(data.profile&&data.foodLibrary){state={...deep(seed),...data,version:2};dataStatus='Imported JSON backup '+file.name;}else throw Error('JSON file does not contain a Fit OS backup.');}
 else {if(!file.name.toLowerCase().endsWith('.xlsx'))throw Error('Please select an .xlsx or JSON backup (old binary .xls unsupported).');let sheets=await window.FitXLSX.read(await file.arrayBuffer());let out=importSheets(sheets);if(!out.touched.length)throw Error('No compatible sheets found. Use the connected template or the older IIM Mumbai workbook.');dataStatus=`${file.name}: recognized ${out.touched.join(', ')} (${out.mapped} populated records or reference rows).`;}
 save();activate('dashboard');toast('Excel imported. Dashboard refreshed ✓');
 }catch(e){console.error('Import error',e);dataStatus='Import failed: '+(e?.message||String(e));render();toast(dataStatus)}finally{$('#fileInput').value=''}}
function registerEvents(){document.addEventListener('click',e=>{let t=e.target.closest('[data-nav],[data-open],[data-close-modal],[data-delete],[data-day],[data-recipe],[data-recipe-filter],[data-grocery-filter],[data-edit-grocery],[data-add-recipe],[data-upload],[data-export],[data-reset]');if(!t)return;
 if(t.dataset.nav){activate(t.dataset.nav);return}
 if(t.dataset.open){showEntry(t.dataset.open);return}
 if(t.hasAttribute('data-close-modal')){closeModal();return}
 if(t.dataset.day){menuDay=t.dataset.day;render();return}
 if(t.dataset.recipe){showRecipe(t.dataset.recipe);return}
 if(t.dataset.recipeFilter){recipeFilter=t.dataset.recipeFilter;render();return}
 if(t.dataset.groceryFilter){groceryFilter=t.dataset.groceryFilter;render();return}
 if(t.dataset.editGrocery){editGrocery(Number(t.dataset.editGrocery));return}
 if(t.dataset.addRecipe){addRecipe(t.dataset.addRecipe);return}
 if(t.hasAttribute('data-upload')){$('#fileInput').click();return}
 if(t.dataset.export){if(t.dataset.export==='xlsx')exportXLSX();if(t.dataset.export==='json')exportJSON();if(t.dataset.export==='csv')exportCSV();return}
 if(t.dataset.delete){let [key,idx]=t.dataset.delete.split(':');if(confirm('Delete this logged record?')){state[key].splice(Number(idx),1);save();render();toast('Entry deleted')}return}
 if(t.hasAttribute('data-reset')){if(confirm('Clear ALL browser records? This cannot be undone. Export a backup first.')){localStorage.removeItem(KEY);state=deep(seed);activate('dashboard');toast('Local browser data reset')}return}
 });document.addEventListener('submit',e=>{if(e.target.id==='entryForm')saveEntry(e);else if(e.target.id==='groceryEditForm')saveGrocery(e);else if(e.target.id==='profileForm'){e.preventDefault();let vals=Object.fromEntries(new FormData(e.target));for(let [k,v] of Object.entries(vals)){state.profile[k]=typeof state.profile[k]==='number'?Number(v):v;}save();render();toast('Targets updated ✓')}});
 document.addEventListener('input',e=>{if(e.target.id==='recipeSearch'){let start=e.target.selectionStart;recipeQuery=e.target.value;render();let el=$('#recipeSearch');if(el){el.focus();el.setSelectionRange(start,start)}}else if(e.target.id==='grocerySearch'){let start=e.target.selectionStart;groceryQuery=e.target.value;render();let el=$('#grocerySearch');if(el){el.focus();el.setSelectionRange(start,start)}}});
 $('#dateInput').value=selectedDate;$('#dateInput').addEventListener('change',e=>{selectedDate=e.target.value||localDate(new Date());render()});$('#fileInput').addEventListener('change',e=>importFile(e.target.files?.[0]));$('#topImport').addEventListener('click',()=>activate('sync'));$('#profileBtn').addEventListener('click',()=>activate('settings'));$('#mobileMenu').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#mobileShade').classList.add('show')});$('#mobileClose').addEventListener('click',closeMenu);$('#mobileShade').addEventListener('click',closeMenu);$('#modalLayer').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.addEventListener('dragover',e=>{if(e.target.closest('#dropZone')){e.preventDefault();e.target.closest('#dropZone').classList.add('drag')}});document.addEventListener('dragleave',e=>{if(e.target.closest('#dropZone'))e.target.closest('#dropZone').classList.remove('drag')});document.addEventListener('drop',e=>{let z=e.target.closest('#dropZone');if(!z)return;e.preventDefault();z.classList.remove('drag');importFile(e.dataTransfer.files?.[0])});
}
